using Astronomy.MediaFactory.Core.KnowledgeFoundation.Catalog;using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Catalog;
public sealed class AstronomyKnowledgeCatalogEntryTests{[Fact]public void KnowledgeCatalogEntry_is_immutable_and_validated(){var m=new Dictionary<string,string>{{"a","b"}};var e=new AstronomyKnowledgeCatalogEntry(new(AstronomyKnowledgeCatalogEntryKind.Domain,"id")," code "," name "," desc ",0,AstronomyKnowledgeDomain.Catalog,metadata:m);m["a"]="c";Assert.Equal("b",e.Metadata["a"]);Assert.Throws<NotSupportedException>(()=>((IDictionary<string,string>)e.Metadata).Add("x","y"));Assert.Throws<ArgumentException>(()=>new AstronomyKnowledgeCatalogEntry(new(AstronomyKnowledgeCatalogEntryKind.Domain,"id")," ","n","d",0));Assert.Throws<ArgumentException>(()=>new AstronomyKnowledgeCatalogEntry(new(AstronomyKnowledgeCatalogEntryKind.Domain,"id"),"c"," ","d",0));Assert.Throws<ArgumentException>(()=>new AstronomyKnowledgeCatalogEntry(new(AstronomyKnowledgeCatalogEntryKind.Domain,"id"),"c","n"," ",0));Assert.Throws<ArgumentOutOfRangeException>(()=>new AstronomyKnowledgeCatalogEntry(new(AstronomyKnowledgeCatalogEntryKind.Domain,"id"),"c","n","d",-1));Assert.Throws<ArgumentOutOfRangeException>(()=>new AstronomyKnowledgeCatalogEntry(new(AstronomyKnowledgeCatalogEntryKind.Domain,"id"),"c","n","d",0,(AstronomyKnowledgeDomain)999));Assert.Throws<ArgumentOutOfRangeException>(()=>new AstronomyKnowledgeCatalogEntry(new(AstronomyKnowledgeCatalogEntryKind.Domain,"id"),"c","n","d",0,family:(AstronomyKnowledgePayloadFamily)999));}}
